  const existing = await memberRepo.findMember(invitation.orgId, userId);

  // Accepting uses the invitation up whoever accepts it; a current member
  // gains nothing from it and keeps their role.
  if (isCurrentMember(existing)) {
    await invitationRepo.markInvitationAccepted(
      invitation.orgId,
      invitation.id,
      acceptedAt,
    );
    return existing;
  }

  // A former member is re-admitted on the membership the workspace already
  // knew rather than given a second row.
  const member = existing
    ? await memberRepo.reactivateMember(
        invitation.orgId,
        existing.id,
        invitation.role,
        invitation.invitedBy,
        acceptedAt,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
      );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );
'''),
])

